// 政策行为数据
export const policyActions = [{'id': 1, 'action': 'Expansionary fiscal policy', 'type': 'fiscal_policy'}, {'id': 2, 'action': 'Increase government spending', 'type': 'fiscal_policy'}, {'id': 3, 'action': 'Increase transfer payments (e.g. unemployment benefits)', 'type': 'fiscal_policy'}, {'id': 4, 'action': 'Decrease taxes', 'type': 'fiscal_policy'}, {'id': 5, 'action': 'Contractionary fiscal policy', 'type': 'fiscal_policy'}, {'id': 6, 'action': 'Decrease government spending', 'type': 'fiscal_policy'}, {'id': 7, 'action': 'Decrease transfer payments', 'type': 'fiscal_policy'}, {'id': 8, 'action': 'Increase taxes', 'type': 'fiscal_policy'}, {'id': 9, 'action': 'Expansionary monetary policy', 'type': 'monetary_policy'}, {'id': 10, 'action': 'Decrease required reserve ratio', 'type': 'monetary_policy'}, {'id': 11, 'action': 'Decrease reserve requirement', 'type': 'monetary_policy'}, {'id': 12, 'action': 'Buy government bonds / securities', 'type': 'monetary_policy'}, {'id': 13, 'action': 'Buy Treasury bonds / bills', 'type': 'monetary_policy'}, {'id': 14, 'action': 'Open market purchase of bonds', 'type': 'monetary_policy'}, {'id': 15, 'action': 'Decrease discount rate', 'type': 'monetary_policy'}, {'id': 16, 'action': 'Decrease interest on reserves', 'type': 'monetary_policy'}, {'id': 17, 'action': 'Decrease administered interest rates', 'type': 'monetary_policy'}, {'id': 18, 'action': 'Contractionary monetary policy', 'type': 'monetary_policy'}, {'id': 19, 'action': 'Increase required reserve ratio', 'type': 'monetary_policy'}, {'id': 20, 'action': 'Increase reserve requirement', 'type': 'monetary_policy'}, {'id': 21, 'action': 'Sell government bonds / securities', 'type': 'monetary_policy'}, {'id': 22, 'action': 'Sell Treasury bonds / bills', 'type': 'monetary_policy'}, {'id': 23, 'action': 'Open market sale of bonds', 'type': 'monetary_policy'}, {'id': 24, 'action': 'Increase discount rate', 'type': 'monetary_policy'}, {'id': 25, 'action': 'Increase interest on reserves', 'type': 'monetary_policy'}, {'id': 26, 'action': 'Increase administered interest rates', 'type': 'monetary_policy'}];

// 经济变量
export const economicVariables = [{'id': 1, 'name': 'Aggregate Demand', 'category': 'macro_indicator'}, {'id': 2, 'name': 'Price Level', 'category': 'macro_indicator'}, {'id': 3, 'name': 'Real GDP', 'category': 'macro_indicator'}, {'id': 4, 'name': 'Unemployment Rate', 'category': 'macro_indicator'}, {'id': 5, 'name': 'Money Supply', 'category': 'financial_indicator'}, {'id': 6, 'name': 'Interest Rate', 'category': 'financial_indicator'}, {'id': 7, 'name': 'Bond Price', 'category': 'financial_indicator'}, {'id': 8, 'name': 'Interest-sensitive Private Spending (Investment & Consumption)', 'category': 'expenditure'}, {'id': 9, 'name': 'Economic Growth (LRAS, PPC)', 'category': 'macro_indicator'}];

// 政策影响关系
export const policyEffects = [{'policyId': 1, 'Unnamed: 1': 'Expansionary fiscal policy', 'variableId': 1, 'Unnamed: 3': 'Aggregate Demand', 'effect': 'increase', 'explanation': 'Expansionary fiscal policy刺激经济，增加AD。政府支出直接影响AD，税和转移支付影响disposable income，间接影响private spending和AD。（但如有deficit，政府借债可能会crowd out部分private spending）'}, {'policyId': 1, 'Unnamed: 1': 'Expansionary fiscal policy', 'variableId': 2, 'Unnamed: 3': 'Price Level', 'effect': 'increase', 'explanation': 'Expansionary fiscal policy刺激经济，增加AD，见AD-AS diagram'}, {'policyId': 1, 'Unnamed: 1': 'Expansionary fiscal policy', 'variableId': 3, 'Unnamed: 3': 'Real GDP', 'effect': 'increase', 'explanation': 'Expansionary fiscal policy刺激经济，增加AD，见AD-AS diagram'}, {'policyId': 1, 'Unnamed: 1': 'Expansionary fiscal policy', 'variableId': 4, 'Unnamed: 3': 'Unemployment Rate', 'effect': 'decrease', 'explanation': '失业率通常与real GDP反向。（Expansionary fiscal policy刺激经济，增加AD，见AD-AS diagram）'}, {'policyId': 1, 'Unnamed: 1': 'Expansionary fiscal policy', 'variableId': 6, 'Unnamed: 3': 'Interest Rate', 'effect': 'increase', 'explanation': 'Expansionary fiscal policy使public savings=tax-(government spending+transfers)降低，减少Supply of Loans（或增加deficit spending进而增加Demand for Loans)，因而利率上升。见loanable funds market diagram'}, {'policyId': 1, 'Unnamed: 1': 'Expansionary fiscal policy', 'variableId': 7, 'Unnamed: 3': 'Bond Price', 'effect': 'decrease', 'explanation': '债券价格与利率反向。（Expansionary fiscal policy使public savings=tax-(government spending+transfers)降低，减少Supply of Loans（或增加deficit spending进而增加Demand for Loans)，因而利率上升。见loanable funds market diagram）'}, {'policyId': 1, 'Unnamed: 1': 'Expansionary fiscal policy', 'variableId': 8, 'Unnamed: 3': 'Interest-sensitive Private Spending (Investment & Consumption)', 'effect': 'decrease', 'explanation': 'Interest-sensitive Private Spending (Investment & Consumption)与利率反向。（Expansionary fiscal policy使public savings=tax-(government spending+transfers)降低，减少Supply of Loans（或增加deficit spending进而增加Demand for 